parameters.jsCode:
const normalizeLink = value => {
  const raw = String(value || '').trim();
  const parts = raw.match(/^(?:https?:\/\/)?([a-z0-9-]+(?:\.[a-z0-9-]+)+)(\/[^\s?#<>"\\]*)?(?:[?#][^\s]*)?$/i);
  if (!parts) return '';
  const host = parts[1].toLowerCase();
  if (!/\.[a-z]{2,63}$/.test(host) || /\.(?:local|localhost|internal|test|invalid|example|onion|lan|home|corp)$/.test(host)) return '';
  const path = parts[2] || '';
  if (/%(?:0[0-9a-f]|1[0-9a-f]|7f|2f|5c)/i.test(path)) return '';
  const scheme = /^http:\/\//i.test(raw) ? 'http://' : 'https://';
  return scheme + host + path;
};
const splitLinks = text => String(text || '').trim().split(/[\s,;]+/).filter(Boolean);
const linksFrom = (website, social) => [...new Set([website, ...splitLinks(social)].map(normalizeLink).filter(Boolean))].slice(0,4);

const line = (value, max) => String(value ?? '').trim().replace(/\s+/g,' ').slice(0,max);
const input = {
  startup: line($json.startup,100),
  pitch: line($json.pitch,320),
  website: line($json.website,400),
  social: line($json.social,1200),
};
const urls = linksFrom(input.website,input.social);
const invalidLinks = [input.website,...splitLinks(input.social)].filter(Boolean).some(value => !normalizeLink(value));
return {json:{input,urls,invalidLinks}};

const d = $json.input;

const keywords = [...new Set(d.keywordsRaw.split(',').map(value=>value.trim()).filter(Boolean))];
const language = d.language === 'Other' ? d.customLanguage : d.language;
const profile = {
  profile_key: 'book-' + d.notebookId,
  startup_name: d.startup,
  competitors: [],
  language, language_choice:d.language, content_type:d.contentType,
  frequency:d.frequency, timezone:'Europe/Paris',
  schedule:{days:d.days.length===2 ? [...d.days].sort((a,b)=>a-b) : [1,4],time:d.time},
};
if (d.positioning) profile.positioning=d.positioning;
if (d.industry) profile.industry=d.industry;
if (keywords.length) profile.keywords=keywords;
if (d.topics) profile.topics=d.topics;
if (d.tone) profile.tone=d.tone;
if (d.publicLinks.length) profile.public_links=d.publicLinks;
const market = [d.industry,...d.topics.split(',').map(value=>value.trim()),...keywords].filter(Boolean).slice(0,4);
const subject = d.startup.replace(/["\\]/g,' ').trim();
const search = market.length ? market.slice(0,2).join(' ') : d.positioning.slice(0,170);
const query = (search ? search : '"'+subject+'" actualités').slice(0,380);
return {json:{profile,query,persist:d.frequency==='Twice per week',trigger:'manual'}};

let src = $json;
if (!src.profile) {
  try { src = $('S2. Find due scheduled slots').item.json; } catch (e) { src = $('1c. Build JSON profile').item.json; }
}
const trig = src.trigger || 'manual';
const runId = trig === 'scheduled'
  ? 'sched-' + String(src.slot_key).replace(/[^a-zA-Z0-9-]+/g, '-') + '-' + require('crypto').randomBytes(8).toString('hex')
  : 'run-' + ($execution.id || Date.now());
return { json: { ctx: { run_id: runId, trigger: trig, profile: src.profile, query: src.query, slot_key: src.slot_key || '', persist: !!src.persist, started_at: new Date().toISOString() } } };

const rows = $input.all().map((i) => i.json).filter((r) => r.profile_key);
const out = [];
rows.forEach((r) => {
  let stored = {};
  try { stored = JSON.parse(r.profile_json || '{}'); } catch (e) { stored = {}; }
  const tz = r.timezone || 'Europe/Paris';
  const now = $now.setZone(tz);
  const days = String(r.schedule_days || '1,4').split(',').map((x) => parseInt(x, 10)).filter((x) => x >= 1 && x <= 7);
  const tp = String(r.schedule_time || '09:00').split(':');
  const slot = now.set({ hour: parseInt(tp[0], 10) || 0, minute: parseInt(tp[1], 10) || 0, second: 0, millisecond: 0 });
  const due = days.indexOf(now.weekday) >= 0 && now.toMillis() >= slot.toMillis() && now.toMillis() < slot.plus({ hours: 1 }).toMillis();
  const slotKey = r.profile_key + '|' + slot.toFormat('yyyy-MM-dd') + '|' + slot.toFormat('HH:mm');
  if (due && r.last_slot_key !== slotKey) {
    const profile = Object.assign({}, stored);
    delete profile.query;
    profile.content_type = r.content_type || profile.content_type;
    profile.language = r.writing_language || profile.language;
    out.push({ json: { profile: profile, query: stored.query, persist: true, trigger: 'scheduled', slot_key: slotKey } });
  }
});
return out;

