parameters.jsCode:
const row = $input.first().json;
if (!row || !row.run_id) return [{ json: { reviewable: false, message: 'No pending review was found for this Run ID.' } }];
if (row.status !== 'Awaiting topic selection') return [{ json: { reviewable: false, message: 'Run ' + row.run_id + ' is not awaiting topic selection (status: ' + row.status + '). A run can be reviewed only once.' } }];
let stored = {};
try { stored = JSON.parse(row.shortlist_json || '{}'); } catch (e) { stored = {}; }
if (!stored.shortlist || !stored.ctx) return [{ json: { reviewable: false, message: 'The stored shortlist for this run is unreadable.' } }];
return [{ json: { reviewable: true, run_id: row.run_id, ctx: stored.ctx, shortlist: stored.shortlist, articles: stored.articles || [] } }];

const j = $json;
const p = j.ctx.profile;
const fr = /^fr(en(ch|çais))?$/i.test(p.language);
const tr=(en,french)=>fr?french:en;
const esc=v=>String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
const date=x=>x.publishedDate?new Date(x.publishedDate).toLocaleDateString(fr?'fr-FR':'en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'Europe/Paris'}):tr('Date to confirm','Date à confirmer');
const link=(x,label)=>/^https:\/\//i.test(x.url||'')?'<a href="'+esc(x.url)+'" target="_blank" rel="noopener noreferrer">'+esc(label)+'</a>':'';
const completeReason = value => {
 const text=String(value??'').trim().replace(/\s+/g,' ');
 const match=text.match(/^.{1,169}?[.!?](?=\s|$)/);
 return match ? match[0] : '';
};
const stories=j.shortlist.stories;
const angles=j.shortlist.angles;
const sources=new Map(stories.map((s,i)=>[s.articleId,i+1]));
const card=(title,meta,body)=>'<div><h3>'+esc(title)+'</h3><p><small>'+esc(meta)+'</small></p>'+body+'</div>';
const group=(title, intro, cards)=>'<div><h2>'+esc(title)+'</h2>'+(intro?'<p>'+esc(intro)+'</p>':'')+'<div>'+cards.join('')+'</div></div>';
const windowDays=j.ctx.search_window||2;
const sourceCards=stories.map((s,i)=>{
  const details=[tr('Source','Source')+' '+(i+1),s.domain,date(s)].filter(Boolean).join(' · ');
  return card(s.headline||s.title,details,'<p>'+esc(s.summary)+'</p><p>'+link(s,tr('Read the article','Lire l’article'))+'</p>');
});
const angleCards=angles.map(a=>{
  const refs=a.articleRefs.map(r=>{
    const number=sources.get(r.articleId);
    const name=[number ? tr('Source','Source')+' '+number : '',r.domain].filter(Boolean).join(' · ');
    const title=link(r,name)||esc(name);
    const caution=r.dateStatus==='doubtful'?' <strong>'+tr('Date to confirm','Date à vérifier')+'</strong>':'';
    return '<li>'+title+caution+(r.explanation?'<p>'+esc(r.explanation)+'</p>':'')+'</li>';
  });
  return '<div><h3>'+esc(tr('Angle','Angle')+' '+a.label)+'</h3><p><strong>'+esc(a.hook)+'</strong></p><p>'+esc(a.stance)+'</p><ul>'+refs.join('')+'</ul></div>';
});
let h=group(tr('Source articles','Articles sources'),tr('Search window','Fenêtre de recherche')+' · '+windowDays+' '+tr('days','jours'),sourceCards);
h+=group(tr('Editorial angles','Angles éditoriaux'),'',angleCards);
const formatLabels={"LinkedIn post":"Post LinkedIn","LinkedIn post + image":"Post LinkedIn avec image","LinkedIn carousel":"Carrousel LinkedIn","Blog article":"Article de blog","Newsletter":"Newsletter","One-pager PDF":"Fiche PDF (une page)"};
const isAvailable=format=>Object.hasOwn(formatLabels,format);
const rec=j.shortlist.formatRecommendation;
const validRecommendation=isAvailable(rec?.format);
const defaultFormat=validRecommendation?rec.format:isAvailable(p.content_type)?p.content_type:'LinkedIn post';
if(validRecommendation){
  h+='<div><h4>'+tr('Suggested format','Format conseillé')+'</h4><p><strong>'+esc(fr?formatLabels[rec.format]:rec.format)+'</strong></p>'+(completeReason(rec.reason)?'<p>'+esc(completeReason(rec.reason))+'</p>':'')+'</div>';
}
const history=(j.ctx.history||[]).slice(0,3);
if(history.length){
  const recent=history.map(r=>'<li>'+esc(r.title)+' <small>· '+esc(date({publishedDate:r.at}))+' · '+esc(formatLabels[r.format]||r.format)+'</small></li>');
  h+='<div><h4>'+tr('Recently approved','Derniers contenus validés')+'</h4><ul>'+recent.join('')+'</ul></div>';
}
return {json:{...j,checkpoint_html:h,default_format:formatLabels[defaultFormat],default_language_choice:({"French": "Français", "English": "Anglais", "German": "Allemand", "Spanish": "Espagnol", "Other": "Autre"})[p.language_choice]||'Français',default_custom_language:p.custom_language||''}};

const ctxItems = $('M2. Rattacher les contenus validés').all();
const rows = $input.all().map((i) => i.json).filter((r) => r.url);
return ctxItems.map((c) => ({ json: { ctx: { ...c.json.ctx, search_window: 30 }, seen: c.json.ctx.trigger === 'manual' && !c.json.ctx.persist ? [] : rows.filter((r) => r.profile_key === c.json.ctx.profile.profile_key).map((r) => r.url) } }));

parameters.jsonBody:
={{ (() => {
  const ctx = $json.ctx;
  const profile = ctx.profile;
  const topics = String(profile.topics || '').split(/[,;\n]+/).map(topic => topic.trim()).filter(Boolean).slice(0, 3);
  const sector = String(profile.industry || '').replace(/^(logiciel|plateforme|software)\s+/i, '');
  const keywords = (profile.keywords || []).map(value=>String(value).trim()).filter(Boolean);
  const normalize = value => value.normalize('NFD').replace(/\p{M}/gu,'').toLowerCase();
  const primary = topics[0] || '';
  const keyWords = value => new Set(normalize(value).match(/\p{L}{3,}/gu)?.map(word=>word.replace(/s$/,'')) || []);
  const core = keyWords(primary);
  const overlap = keywords.find(keyword => [...keyWords(keyword)].some(word=>core.has(word)));
  const subject = primary.length >= 24 ? primary
    : overlap && overlap.length > primary.length ? overlap
    : primary && keywords.length ? primary+' '+keywords[0]
    : primary || keywords[0] || sector || ctx.query;
  const query = [subject, /^(French|Français)$/i.test(profile.language) ? 'actualités' : 'news'].filter(Boolean).join(' ').slice(0,350);
  return { query, topic: "news", start_date: new Date(Date.now() - ctx.search_window * 86400000).toISOString().slice(0, 10), max_results: 12, exclude_domains: ["tavily.com", "facebook.com", "instagram.com", "tiktok.com", "youtube.com"], include_answer: false, search_depth: "advanced", include_raw_content: "text" };
})() }}

parameters.jsCode:
const ctx = $('2.0b Pack run context and seen URLs').item.json.ctx;
const e = $json.error;
const msg = (e && e.message) ? e.message : String(e || 'unknown error');
return { json: { ctx: ctx, outcome_status: 'Search API failure', message: 'The news search API failed after two attempts: ' + msg + '. This is an API failure, not an absence of news. Nothing was drafted.' } };

const out = [];
const packs = $('2.0b Pack run context and seen URLs').all();
$input.all().forEach((it, idx) => {
  let pi = idx;
  if (typeof it.pairedItem === 'number') pi = it.pairedItem;
  else if (it.pairedItem && typeof it.pairedItem.item === 'number') pi = it.pairedItem.item;
  const pack = packs[pi] || packs[0];
  const results = Array.isArray(it.json.results) ? it.json.results : [];
  results.forEach((r, n) => {
    out.push({ json: { ctx: pack.json.ctx, seen: pack.json.seen, article: { articleId: 'art-' + (n + 1), url: String(r.url || '').trim(), title: String(r.title || '').trim(), publishedDate: r.published_date || r.publishedDate || '', rawContent: typeof r.raw_content === 'string' ? r.raw_content.slice(0, 12000) : '', excerpt: String(r.content || '').trim(), score: r.score === undefined ? null : r.score } } });
  });
});
return out;

const arts = $('2a. One item per result').all();
const items = $input.all();
const nowMs = Date.now();
const seenByRun = {};
function norm(value) {
  const match = String(value || '').trim().match(/^https?:\/\/([^/?#]+)([^?#]*)(?:\?([^#]*))?/i);
  if (!match) return String(value || '').trim();
  const [, host, path, query = ''] = match;
  const params = query.split('&').filter(part => part && !/^(utm_[^=]*|fbclid|gclid|msclkid|mc_cid|mc_eid|igshid|trk)(=|$)/i.test(part)).sort();
  return host.toLowerCase().replace(/^www\./, '').replace(/:443$/, '') + path.replace(/\/+$/, '') + (params.length ? '?' + params.join('&') : '');
}
const out = [];
items.forEach((it, idx) => {
  let pi = idx;
  if (typeof it.pairedItem === 'number') pi = it.pairedItem;
  else if (it.pairedItem && typeof it.pairedItem.item === 'number') pi = it.pairedItem.item;
  const base = (arts[pi] || arts[idx]).json;
  const a = base.article;
  const ctx = base.ctx;
  if (!seenByRun[ctx.run_id]) seenByRun[ctx.run_id] = {};
  const reasons = [];
  let domain = '';
  let httpsOk = false;
  const um = String(a.url).match(/^https:\/\/([a-zA-Z0-9.-]+)(:[0-9]+)?([/?#]|$)/);
  if (um && um[1].indexOf('.') > 0 && um[1].indexOf('..') < 0 && !/\s/.test(a.url)) {
    httpsOk = true;
    domain = um[1].toLowerCase().replace(/^www\./, '');
  }
  if (/^https:\/\/(?:www\.)?apprentus\.[a-z.]+\/(?:cours-|private-lessons\/)/i.test(a.url) || /cours particuliers à domicile par nos professeurs|find (?:a |your )?(?:private )?tutor near you/i.test(a.title)) reasons.push('Course listing, not a dated news article');
  if (/(^|\.)linkedin\.com$/.test(domain) && /\/(?:jobs|job)\b/i.test(a.url.replace(/^https:\/\/[^/]+/i, ''))) reasons.push('Offre d’emploi, pas une actualité éditoriale');
  if (/(^|\.)(indeed\.[a-z.]+|glassdoor\.[a-z.]+|welcometothejungle\.com)$/.test(domain) && /\/(?:jobs|job|viewjob|emplois)(?:[/?#]|$)/i.test(a.url.replace(/^https:\/\/[^/]+/i, ''))) reasons.push('Offre d’emploi, pas une actualité éditoriale');
  const path = a.url.replace(/^https:\/\/[^/]+/i, '');
  if (/\/(?:catalogue-formations|formations|explorer-metiers|fiche-metier|emploi|topic)(?:[/?#]|$)/i.test(path)
