#n8n-form .html li+li{margin-top:7px}
#n8n-form .html li strong{color:#71430c;background:#fff0d5;border-radius:5px;padding:2px 5px;font-size:12px;white-space:nowrap}
#n8n-form .html a{color:#4d38bc;text-underline-offset:3px;font-weight:650}
#n8n-form .form-label{display:block;margin:0 0 6px;font-size:14px;font-weight:700;line-height:1.35;color:#302940}
#n8n-form :is(.form-input,select,textarea){box-sizing:border-box;width:100%;min-height:44px;border:1px solid #d9d0e8;border-radius:10px;background:#faf8fd;font:inherit;font-size:16px;line-height:1.45;padding:10px 12px;color:#251d39}
#n8n-form textarea.form-input{min-height:90px;resize:vertical}
#n8n-form :is(input,select,textarea,button,a):focus-visible{outline:2px solid #5d45ca;outline-offset:2px}
#n8n-form .error-hidden{display:none!important}
#n8n-form .error-show{color:#9b2624;font-size:13px}
#n8n-form:has(#field-4 option:checked:not([value="Autre"])) .form-group:has(#field-5){display:none}
#submit-btn{min-height:46px;margin-top:22px;border-radius:10px;background:#4d38bc;color:#fff;font-size:16px;font-weight:700}
#submit-btn:hover{background:#3e2c9f}
@media(max-width:620px){#n8n-form .inputs-wrapper{grid-template-columns:minmax(0,1fr);gap:14px}}

