const f = $json;
const cp = $('3z. Prepare checkpoint 1 view').item.json;
const ctx = cp.ctx;
const sl = cp.shortlist;
const TYPES = ["LinkedIn post", "LinkedIn post + image", "LinkedIn carousel", "Blog article", "Newsletter", "One-pager PDF"];
const LANGS = ['English', 'French', 'German', 'Spanish', 'Other'];
const angleLabel = String(f['Angle'] || '').split(' · ')[0].trim();
if (['Abort','Arrêter ici'].includes(angleLabel)) return { json: { valid: false, aborted: true, problems: [], ctx: ctx } };
const note = String(f['Your 1 to 2 sentences'] || '').trim();
const formatInput = String(f['Content type (this run only)'] || f['Format du contenu'] || '').trim();
const formatKeys = {"Post LinkedIn": "LinkedIn post", "Post LinkedIn avec image": "LinkedIn post + image", "Carrousel LinkedIn": "LinkedIn carousel", "Article de blog": "Blog article", "Newsletter": "Newsletter", "Fiche PDF (une page)": "One-pager PDF"};
const format = Object.hasOwn(formatKeys,formatInput) ? formatKeys[formatInput] : formatInput;
let language = String(f['Writing language (this run only)'] || '').trim();
language = ({"Français": "French", "Anglais": "English", "Allemand": "German", "Espagnol": "Spanish", "Autre": "Other"})[language] || language;
const custom = String(f['Custom language (only if Other)'] || '').trim();
const cf = f['Source confirmation (needed only if the chosen angle uses a DOUBTFUL-date article)'];
const confirmed = (Array.isArray(cf)?cf:[cf]).some(v=>['J’ai ouvert la source : la date de l’événement (pas seulement celle de l’article) est correcte','I checked the source date and it fits the search window'].includes(v));
const problems = [];
const angle = sl.angles.find((a) => a.label === angleLabel);
if (!angle) problems.push('Choisissez un des angles proposés.');
if (TYPES.indexOf(format) < 0) problems.push('Unknown content type.');
if (LANGS.indexOf(language) < 0) problems.push('Unknown writing language.');
if (language === 'Other') { if (!custom) problems.push('A custom language is required when Writing language is Other.'); else language = custom; }
const known = {};
cp.articles.forEach((a) => { known[a.articleId] = a; });
let refs = [];
let doubtful = [];
if (angle) {
  refs = angle.articleRefs;
  if (!refs.length) problems.push('The chosen angle has no valid reference.');
  refs.forEach((r) => { if (!known[r.articleId]) problems.push('Reference ' + r.articleId + ' is not a verified source.'); });
  doubtful = refs.filter((r) => r.dateStatus === 'doubtful');
  if (doubtful.length && !confirmed) problems.push('Vérifiez la date de la source avant de choisir cet angle.');
}
const authorizedArticles = refs.filter((r) => known[r.articleId]).map((r) => known[r.articleId]);
return { json: { valid: problems.length === 0, aborted: false, problems: problems, ctx: ctx, selection: { angle: angle, angleLabel: angleLabel, note: note, format: format, language: language, doubtfulIds: doubtful.map((d) => d.articleId), doubtfulConfirmed: doubtful.length ? confirmed : null }, authorizedArticles: authorizedArticles } };

