  const text = String(a.text || '').slice(0, 2500);
  const parts = text.match(/[^.!?\n]+(?:[.!?]+|$)/g) || [];
  const excerpts = parts.map((part) => part.trim()).filter((part) => part.length >= 20 && !/(cookie|auto-?compl[ée]tion|appareils tactiles|gestes de balayage|newsletter|abonnez|inscrivez-vous|se connecter|mot de passe|tous droits r[ée]serv[ée]s|partager sur|lire aussi|publicit[ée]|javascript)/i.test(part)).slice(0, 20);
  (excerpts.length ? excerpts : [text.trim()]).filter(Boolean).forEach((excerpt, index) => {
