const st = $('5k. Prepare checkpoint 2 view').item.json;
const f = $json;
const decision = String(f['Decision'] || '').trim();
const d = st.draft;
const original = d.draftText;
const finalText = Object.hasOwn(f, 'editedText')
  ? String(f.editedText ?? '')
  : String(f['Edited content (optional)'] || '').trim() || original;
const changed = finalText !== original;
const fmt = d.format;
const pdfFormat = Boolean(st.spec.pdf);
const blocked = [];
if (!['Valider le contenu'].includes(decision)) blocked.push('Choisissez une décision.');
if (!finalText.trim()) blocked.push('Ajoutez du texte dans l’éditeur avant de valider.');
const auth = {};
st.authorizedUrls.forEach((u) => { auth[u] = true; });
let unverified = [];
if (changed) {
  const found = (finalText.match(/https?:\/\/[^\s)<>"'\]]+/g) || []).map((u) => u.replace(/[.,;:!?]+$/, ''));
  found.forEach((u) => { if (!auth[u] && unverified.indexOf(u) < 0) unverified.push(u); });
} else {
  unverified = st.link_check.unverified || [];
}
if (unverified.length) blocked.push('Unverified link(s) not in the sources authorised for the chosen angle: ' + unverified.join(', '));
if (pdfFormat && !changed && st.pdf_status !== 'ok') blocked.push('The required PDF asset is missing or invalid: ' + (st.pdf_message || 'not rendered'));
if (fmt === 'LinkedIn carousel') {
  const slides = finalText.trim().split(/\r?\n\s*\r?\n/).filter(Boolean);
  if (slides.length !== 3 || slides.some(slide => slide.length > 240 || /\S{35,}/u.test(slide))) {
    blocked.push('Le carrousel doit comporter trois blocs séparés par une ligne vide, de 240 caractères chacun au maximum.');
  }
}
const scheduleAt = null;
let route = 'manual';
if (fmt === 'Gated content (downloadable PDF)') route = 'gated';
else if (pdfFormat) route = 'manual';
let hash = 5381;
for (let i = 0; i < finalText.length; i++) { hash = ((hash * 33) ^ finalText.charCodeAt(i)) >>> 0; }
const version = 'v' + hash.toString(16);
const approval = { decision: decision, finalText: finalText, changed: changed, scheduleAt: scheduleAt, blocked: blocked, ok: blocked.length === 0, route: route, needsRegen: pdfFormat && changed && blocked.length === 0, version: version, assetId: 'gate-' + st.ctx.run_id + '-' + version };
return { json: Object.assign({}, st, { approval: approval, phase: 'approval', draft: Object.assign({}, d, { title: (d.format === 'Newsletter' && finalText.split(/\r?\n/).map(s=>s.trim()).find(s=>s && !/^(objet|subject)\s*:?$/i.test(s))) || d.title, draftText: finalText, originalDraftText: original }) }) };

const st = $('6c. Validate approved content').item.json;
const handoff = $('6o. Build manual handoff page').item.json;
const token = handoff.publicationToken;
const supported = ['LinkedIn post','LinkedIn post + image'].includes(st.draft.format) || (st.draft.format === 'LinkedIn carousel' && !!handoff.carouselPdf);
if (!supported || st.phase !== 'approval' || st.approval.ok !== true || st.approval.decision !== 'Valider le contenu' || !token || $json.body?.publicationToken !== token) {
  return { json: { ...st, guard: { duplicate: true, invalidRequest: true } } };
}
const sd = $getWorkflowStaticData('global');
if (!sd.published) sd.published = {};
const key = st.ctx.run_id + ':' + st.approval.version;
const duplicate = !!sd.published[key];
if (!duplicate) sd.published[key] = { claimedAt: new Date().toISOString() };
const out = { json: { ...st, guard: { key, duplicate } } };
const mime=handoff.linkedinImageMime;
if(!duplicate && st.draft.format==='LinkedIn post + image' && ['image/jpeg','image/png'].includes(mime)) {
  const data=String(st.image_b64||'').replace(/\s+/g,'');
  const expected=mime==='image/png'?'iVBORw0KGgo':'/9j/';
  if(!data.startsWith(expected)) return {json:{...st,guard:{duplicate:true,invalidRequest:true}}};
  out.binary={data:{data,mimeType:mime,fileName:mime==='image/png'?'visuel.png':'visuel.jpg'}};
}
return out;

const st = $('7a2. Duplicate-publish guard').item.json;
const e = $json.error;
const msg = (e && e.message) ? e.message : String(e || 'unknown error');
const uncertain = /timeout|timed out|ECONNRESET|socket|ETIMEDOUT|50[0-9]/i.test(msg);
return { json: {
  status: uncertain ? 'Outcome uncertain' : 'Publishing failed',
  message: uncertain ? 'LinkedIn may already have received this post. Check your LinkedIn profile BEFORE posting manually to avoid a duplicate.' : 'The post was not published. Post the approved draft manually.',
  error: msg,
  approved_text: st.approval.finalText,
  references: st.draft.sources,
  run_id: st.ctx.run_id
} };

const j = $json;
const buf = Buffer.from(String(j.pdf_b64 || ''), 'base64');
const bin = await this.helpers.prepareBinaryData(buf, j.pdf_filename || 'one-pager.pdf', 'application/pdf');
const refs = j.draft.sources.map((s, i) => (i + 1) + '. ' + s.url).join(' | ');
return { json: { filename: j.pdf_filename, message: 'Approved PDF. Sources: ' + refs }, binary: { data: bin } };

const j = $json;
const d = j.draft;
const final = j.approval.finalText;
const esc = value => String(value ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
const names = {'LinkedIn post':'Post LinkedIn','LinkedIn post + image':'Post LinkedIn avec image','LinkedIn carousel':'Carrousel LinkedIn','Blog article':'Article de blog','Newsletter':'Newsletter','One-pager PDF':'Fiche PDF'};
const title = d.title || names[d.format] || d.format;
const safeLinks = [...new Set(d.sources.map(s=>s.url).filter(u=>/^https?:\/\//i.test(u)))];
const file = (name,mime,bytes,label) => '<a class="file" download="'+esc(name)+'" href="data:'+mime+';base64,'+bytes+'">'+esc(label)+'</a>';
const base64 = value => Buffer.from(value,'utf8').toString('base64');
const blocks = final.trim().split(/\r?\n\s*\r?\n/).filter(Boolean);
const appendix = [file('texte-valide.txt','text/plain;charset=utf-8',base64(final),'Télécharger le texte')];
let content = '<section class="copy">'+blocks.map(b=>'<p>'+esc(b)+'</p>').join('')+'</section>';
if(d.format==='One-pager PDF'){
  if(j.pdf_status!=='ok'||!Buffer.from(j.pdf_b64||'','base64').subarray(0,5).equals(Buffer.from('%PDF-'))) throw new Error('Le moteur PDF n’a pas produit de fichier valide.');
  appendix.push(file('fiche.pdf','application/pdf',j.pdf_b64,'Télécharger le PDF'));
}
const imageData=String(j.image_b64||'').replace(/\s+/g,'');
const imageMime=imageData.startsWith('/9j/')?'image/jpeg':imageData.startsWith('iVBORw0KGgo')?'image/png':'';
const imageExtension=imageMime==='image/png'?'png':'jpg';
const linkedinImageMime=d.format==='LinkedIn post + image'?imageMime:'';
if(imageMime){
  content += '<figure><img alt="Illustration générée pour le brouillon" src="data:'+imageMime+';base64,'+imageData+'"></figure>';
  appendix.push(file('visuel.'+imageExtension,imageMime,imageData,'Télécharger le visuel'));
}
const slides=[];
const pages=[];
let carouselPdf='';
let unsupportedPdfText=false;
const pdfText=value=>{
  const extra={'€':128,'‚':130,'ƒ':131,'„':132,'…':133,'†':134,'‡':135,'ˆ':136,'‰':137,'Š':138,'‹':139,'Œ':140,'Ž':142,'‘':145,'’':146,'“':147,'”':148,'•':149,'–':150,'—':151,'˜':152,'™':153,'š':154,'›':155,'œ':156,'ž':158,'Ÿ':159};
  return Array.from(String(value)).map(c=>{
    const char=c.charCodeAt(0);
    const value=Object.hasOwn(extra,c)?extra[c]:c==='\u202f'||c==='\u2009'?32:char;
    if(value<32||value>255){unsupportedPdfText=true;return '';}
    return '\\'+value.toString(8).padStart(3,'0');
  }).join('');
};
const pdfLine=(value,size,x,y)=>'BT /F2 '+size+' Tf 1 0 0 1 '+x+' '+(1080-y)+' Tm ('+pdfText(value)+') Tj ET\n';

if(d.format==='LinkedIn carousel'){
  if(blocks.length!==3) throw new Error('Un carrousel doit contenir trois blocs séparés par une ligne vide.');
  const wrap = (input, W=30) => {
    const lines=[];
    let line='';
    for(const word of input.replace(/\s+/g,' ').split(' ')){
      if(line && (line+' '+word).length>W){ lines.push(line);line=word; }
      else line+=(line?' ':'')+word;
    }
    if(line)lines.push(line);
    return lines;
  };
  for(const [i,block] of blocks.entries()){
    let FS=54, LH=70, lines=wrap(block,28);
    if(lines.length>10 || lines.some(line=>line.length>32)){ FS=46; LH=58; lines=wrap(block,34); }
    if(lines.length>13 || lines.some(line=>line.length>38)) throw new Error('La diapositive '+(i+1)+' dépasse la capacité du gabarit.');
    const Y0=Math.max(300, Math.round(560-(lines.length*LH)/2));
    let srcDom=''; try{ const pool=[].concat((typeof j!=='undefined'&&j&&(j.authorizedUrls||[]))||[], (typeof j!=='undefined'&&j&&(j.authorizedArticles||[]).map(x=>x.url))||[], (typeof d!=='undefined'&&d&&(d.sources||[]).map(s=>s&&(s.url||s)))||[]); const u=pool.map(String).find(x=>/^https?:/.test(x)); if(u) srcDom=new URL(u).hostname.replace(/^www\./,''); }catch(e){}
    const foot = i<2 ? '<text x="974" y="960" text-anchor="end" font-family="sans-serif" font-size="30" font-weight="bold" fill="#c3a6ff">Suite →</text>' : (srcDom ? '<text x="106" y="960" font-family="sans-serif" font-size="26" fill="#c3a6ff">Source : '+esc(srcDom)+'</text>' : '');
    const svg='<svg xmlns="http://www.w3.org/2000/svg" width="1080" height="1080" viewBox="0 0 1080 1080"><rect width="1080" height="1080" fill="#f3f0ff"/><rect x="60" y="60" width="960" height="960" rx="56" fill="#211643"/><rect x="106" y="114" width="112" height="10" rx="5" fill="#c3a6ff"/><text x="106" y="205" font-family="sans-serif" font-size="32" font-weight="bold" fill="#c3a6ff">CARROUSEL · '+(i+1)+' / 3</text><text font-family="sans-serif" font-size="'+FS+'" font-weight="bold" fill="#fff">'+lines.map((l,n)=>'<tspan x="106" y="'+(Y0+n*LH)+'">'+esc(l)+'</tspan>').join('')+'</text>'+foot+'</svg>';
    const paint='0.95 0.94 1 rg 0 0 1080 1080 re f\n0.13 0.09 0.26 rg 60 60 960 960 re f\n0.76 0.65 1 rg 106 957 112 9 re f\n';
    pages.push(paint+pdfLine('CARROUSEL · '+(i+1)+' / 3',32,106,205)
      +'1 1 1 rg\n'+lines.map((l,k)=>pdfLine(l,Math.min(FS,Math.floor(864/Math.max(1,l.length*0.88))),106,Y0+k*LH)).join('')
      +'0.76 0.65 1 rg\n'+(i<2?pdfLine('Suite',30,885,960):srcDom?pdfLine('Source : '+srcDom,26,106,960):''));
    slides.push(svg);
  }
  if(!unsupportedPdfText){
    const NL='\n';
  const buildPdf = (pages) => {
    const objs = [];
    const n = pages.length;
    objs[1] = '<< /Type /Catalog /Pages 2 0 R >>';
    const kids = [];
    for (let i = 0; i < n; i++) kids.push((5 + 2 * i) + ' 0 R');
    objs[2] = '<< /Type /Pages /Kids [' + kids.join(' ') + '] /Count ' + n + ' >>';
    objs[3] = '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>';
    objs[4] = '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>';
    pages.forEach((stream, i) => {
      objs[5 + 2 * i] = '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 1080 1080] /Resources << /Font << /F1 3 0 R /F2 4 0 R >> >> /Contents ' + (6 + 2 * i) + ' 0 R >>';
      objs[6 + 2 * i] = '<< /Length ' + stream.length + ' >>' + NL + 'stream' + NL + stream + 'endstream';
    });
    let out = '%PDF-1.4' + NL;
    const offsets = [];
    for (let k = 1; k < objs.length; k++) { offsets[k] = out.length; out += k + ' 0 obj' + NL + objs[k] + NL + 'endobj' + NL; }
    const xref = out.length;
    out += 'xref' + NL + '0 ' + objs.length + NL + '0000000000 65535 f ' + NL;
    for (let k = 1; k < objs.length; k++) out += ('0000000000' + offsets[k]).slice(-10) + ' 00000 n ' + NL;
    out += 'trailer' + NL + '<< /Size ' + objs.length + ' /Root 1 0 R >>' + NL + 'startxref' + NL + xref + NL + '%%EOF' + NL;
    return Buffer.from(out, 'latin1');
  };
    carouselPdf=buildPdf(pages).toString('base64');
    appendix.push(file('carrousel-linkedin.pdf','application/pdf',carouselPdf,'Télécharger le carrousel PDF'));
  }
  content='<section class="slides">'+slides.map((svg,i)=>'<figure><img alt="Diapositive '+(i+1)+'" src="data:image/svg+xml;base64,'+base64(svg)+'"><button type="button" data-slide="'+(i+1)+'">Télécharger le PNG</button></figure>').join('')+'</section>';
}
// LINK_V2 personal notebook link
let __code=''; try { __code = String($('1b7. Vérifier le profil prérempli').first().json.notebook || '').trim().toLowerCase(); } catch (e) {}
if (/^[a-f0-9]{32}$/.test(__code)) { const __u = 'https://assemeak.app.n8n.cloud/form/founder-post-agent-carnet?carnet=' + __code; content += '<section style="margin-top:16px;padding:14px;border-radius:12px;background:#f3f0ff"><strong>Votre lien personnel</strong><p>Ajoutez ce lien à vos favoris : il rouvre votre carnet sans code à recopier. Ne le partagez pas.</p><p><a href="' + __u + '">' + esc(__u) + '</a></p></section>'; }
const script='<script>document.querySelectorAll("[data-slide]").forEach(button=>button.onclick=async()=>{const img=button.parentElement.querySelector("img");await img.decode();const canvas=document.createElement("canvas");canvas.width=canvas.height=1080;canvas.getContext("2d").drawImage(img,0,0);const a=document.createElement("a");a.href=canvas.toDataURL("image/png");a.download="slide-"+button.dataset.slide+".png";a.click();});</script>';
const start='<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(title)+'</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f0ff;color:#211643;font:17px/1.6 system-ui,sans-serif}main{max-width:900px;margin:32px auto;padding:0 18px}header,section,footer{background:white;padding:24px;margin:18px 0;border-radius:22px}header{background:#30224f;color:white}h1{margin:.25em 0;line-height:1.1}header small{color:#e9dff7}header small:before{content:"Étape 5 sur 5 · Remise · ";color:#e9dff7}[data-flow-sound]{background:#fff;color:#4d38bc;border:1px solid #daceef;font-size:14px}p{white-space:pre-wrap;overflow-wrap:anywhere}img{max-width:100%;display:block;border-radius:15px}figure{margin:0 0 16px}.file,button{display:inline-block;border:0;border-radius:9px;padding:10px 14px;background:#5936a8;color:#fff;margin:5px;font:inherit;cursor:pointer;text-decoration:none}.slides{display:grid;grid-template-columns:repeat(auto-fit,minmax(215px,1fr));gap:14px}footer a{overflow-wrap:anywhere}button:disabled{opacity:.56;cursor:wait}</style><body><main><header><small>'+esc(names[d.format]||d.format)+'</small><h1>'+esc(title)+'</h1></header>';
const sources=safeLinks.length?'<footer><strong>Sources consultées</strong><ul>'+safeLinks.map(u=>'<li><a href="'+esc(u)+'">'+esc(u)+'</a></li>').join('')+'</ul></footer>':'';
const publishable = j.phase === 'approval' && j.approval.ok === true && (['LinkedIn post','LinkedIn post + image'].includes(d.format) || Boolean(carouselPdf));
const resumeUrl = publishable ? String($execution.resumeUrl || '') : '';
const publicationToken = /^https:\/\//.test(resumeUrl) ? require('crypto').randomBytes(24).toString('hex') : '';
const textOnlyFallback = d.format === 'LinkedIn post + image' && !linkedinImageMime;
const publicationLabel = textOnlyFallback ? 'Publier le texte seul sur LinkedIn · Hotel Trivia' : 'Publier sur LinkedIn · Hotel Trivia';
const publicationHelp = carouselPdf ? 'Le PDF de trois pages sera publié sur Hotel Trivia.'
  : linkedinImageMime ? 'Le texte validé et le visuel seront publiés sur Hotel Trivia.'
  : textOnlyFallback ? 'Le visuel est indisponible. Cette action publie uniquement le texte validé sur Hotel Trivia.'
  : 'Le texte validé sera publié sur Hotel Trivia.';
const publish = publicationToken ? '<section><h2>Publier sur LinkedIn</h2><p>'+publicationHelp+'</p><form method="post" action="'+esc(resumeUrl)+'"><input type="hidden" name="publicationToken" value="'+publicationToken+'"><button id="publish-linkedin" type="submit" disabled>'+publicationLabel+'</button></form><script>(()=>{const button=document.getElementById("publish-linkedin");if(!button)return;setTimeout(()=>{button.disabled=false;},4000);button.form.addEventListener("submit",()=>{button.disabled=true;button.textContent="Publication en cours…";});})();</script></section>' : '';
