const base = $('1b4. Describe missing context').item.json;
const clean = (value, max) => typeof value === 'string'
  ? value.replace(/[\u0000-\u001f<>]/g,' ').replace(/\s+/g,' ').trim().slice(0,max) : '';
const canonical = value => value.normalize('NFD').replace(/\p{M}/gu,'').toLowerCase().replace(/[^\p{L}\p{N}]/gu,'');
const equivalent = (original, proposed) => {
  const a = canonical(original);
  const b = canonical(proposed);
  if (a === b) return true;
  // Allow one insertion, deletion or substitution in a reasonably distinctive name.
  if (Math.min(a.length,b.length) < 5 || Math.abs(a.length-b.length) > 1) return false;
  const [short,long] = a.length <= b.length ? [a,b] : [b,a];
  let i = 0, j = 0, differences = 0;
  while (i < short.length && j < long.length) {
    if (short[i] === long[j]) { i++; j++; continue; }
    if (++differences > 1) return false;
    if (short.length === long.length) i++;
    j++;
  }
  return differences + long.length - j <= 1;
};
let suggestion = {};
const raw = String($json.text || '');
try { suggestion = JSON.parse(raw.slice(raw.indexOf('{'),raw.lastIndexOf('}')+1)) || {}; } catch {}
const input = base.input;
const name = clean(suggestion.name,100);
const quote = clean(suggestion.nameQuote,250);
const verified = name && quote.includes(name) && base.sources.some(source => clean(source.text,3500).includes(quote));
const startup = verified && (!input.startup || equivalent(input.startup,name)) ? name : input.startup;
