const industry = clean(suggestion.industry,120);
const list = values => Array.isArray(values) ? [...new Set(values.map(value=>clean(value,70)).filter(Boolean))].slice(0,3).join(', ') : '';
const keywords = list(suggestion.keywords);
const topics = list(suggestion.topics);
const esc = value => String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const shortPitch = pitch.trim().split(/\s+/).filter(Boolean).length < 8;
