const text = (label,key,defaultValue,extras={}) => field(label,key,{fieldType:'text',defaultValue,...extras});
const dropdown = (label,key,choices,defaultValue,requiredField=false) => field(label,key,{
  fieldType:'dropdown', defaultValue, requiredField, fieldOptions:{values:choices.map(option=>({option}))},
});
let __linkCode = ''; try { __linkCode = String($('1. Receive founder profile').first().json.carnet || '').trim().toLowerCase(); } catch (e) {}
const __fromLink = /^[a-f0-9]{32}$/.test(__linkCode);
const privateCode = __fromLink ? __linkCode : require('crypto').randomBytes(16).toString('hex');
const fields = [
  {fieldType:'html',html:status + warning + (consulted.length ? '<p><strong>Pages consultées</strong> · '+consulted.join(' · ')+'</p>' : '')},
  text('Code de votre carnet éditorial','notebook',privateCode,{requiredField:true,placeholder:'32 caractères'}),
