  text('Nom de l’entreprise','startup',startup,{requiredField:true}),
  text('Secteur de vos clients','industry',industry,{placeholder:'Ex. Formation en ligne'}),
  field('Pitch en une phrase','pitch',{fieldType:'textarea',defaultValue:pitch}),
  text('Site web','website',input.website),
  text('Liens de réseaux sociaux','social',input.social),
  text('Mots-clés','keywords',keywords,{placeholder:'Séparés par des virgules'}),
  text('Sujets à suivre','topics',topics,{placeholder:'Ex. Nouvelles pratiques, annonces, tendances'}),
  dropdown('Langue de rédaction','language',Object.keys(settings.languages),'Français',true),
  text('Autre langue','customLanguage','',{placeholder:'Si vous avez choisi Autre'}),
  dropdown('Ton','tone',Object.keys(settings.tones),'Clair et professionnel',true),
