const settings = {"languages": {"Français": "French", "Anglais": "English", "Allemand": "German", "Espagnol": "Spanish", "Autre": "Other"}, "tones": {"Clair et professionnel": "Clair et professionnel, précis et accessible", "Conversationnel": "Conversationnel, naturel et direct", "Pédagogique": "Pédagogique, avec des explications concrètes", "Expert et analytique": "Expert et analytique, orienté données", "Énergique": "Énergique, avec un rythme dynamique"}, "frequencies": {"Une seule fois": "Run once", "Deux fois par semaine": "Twice per week"}, "days": ["Lundi", "Mardi", "Mercredi", "Jeudi", "Vendredi", "Samedi", "Dimanche"], "hours": ["00:00", "01:00", "02:00", "03:00", "04:00", "05:00", "06:00", "07:00", "08:00", "09:00", "10:00", "11:00", "12:00", "13:00", "14:00", "15:00", "16:00", "17:00", "18:00", "19:00", "20:00", "21:00", "22:00", "23:00"]};

const normalizeLink = value => {
  const raw = String(value || '').trim();
  const parts = raw.match(/^(?:https?:\/\/)?([a-z0-9-]+(?:\.[a-z0-9-]+)+)(\/[^\s?#<>"\\]*)?(?:[?#][^\s]*)?$/i);
  if (!parts) return '';
  const host = parts[1].toLowerCase();
  if (!/\.[a-z]{2,63}$/.test(host) || /\.(?:local|localhost|internal|test|invalid|example|onion|lan|home|corp)$/.test(host)) return '';
  const path = parts[2] || '';
  if (/%(?:0[0-9a-f]|1[0-9a-f]|7f|2f|5c)/i.test(path)) return '';
  const scheme = /^http:\/\//i.test(raw) ? 'http://' : 'https://';
  return scheme + host + path;
};
const splitLinks = text => String(text || '').trim().split(/[\s,;]+/).filter(Boolean);
const linksFrom = (website, social) => [...new Set([website, ...splitLinks(social)].map(normalizeLink).filter(Boolean))].slice(0,4);

const line = (value,max) => String(value ?? '').replace(/[\u0000-\u001f<>]/g,' ').replace(/\s+/g,' ').trim().slice(0,max);
const j = $json;
const choice = (map,value) => Object.hasOwn(map,value) ? map[value] : '';
const input = {
  startup:line(j.startup,100),
  positioning:line(j.pitch,320),
  industry:line(j.industry,120),
  keywordsRaw:line(j.keywords,240),
  topics:line(j.topics,240),
  language:choice(settings.languages,j.language || 'Français'),
  customLanguage:line(j.customLanguage,70),
  contentType:'LinkedIn post',
  frequency:choice(settings.frequencies,j.frequency),
  tone:choice(settings.tones,j.tone || 'Clair et professionnel'),
  publicLinks:linksFrom(j.website,j.social),
  days:[settings.days.indexOf(j.day1)+1,settings.days.indexOf(j.day2)+1].filter(Boolean),
  time:settings.hours.includes(j.hour) ? j.hour : '09:00',
};
const errors = [];
const unreadable = value => {
  const raw = String(value || '').trim();
  if (!raw) return false;
  const folded = raw.normalize('NFKD').replace(/\p{M}/gu, '').toLowerCase();
  const words = folded.match(/\p{L}+/gu) || [];
  if (!words.length) return true;
  return words.every(word => /^(?:test\d*|asdf.*|qwerty.*|azerty.*|zxcv.*|sd[fgh].*|jkl.*|blabla.*|xxx.*|lorem|ipsum|(.)\1{3,})$/u.test(word) || (/^[a-z]{6,}$/.test(word) && !/[aeiouy]/.test(word)));
};
for (const [label, value] of [['Nom de l’entreprise', input.startup], ['Pitch', input.positioning], ['Secteur', input.industry], ['Mots-clés', input.keywordsRaw], ['Sujets à suivre', input.topics]]) {
  if (unreadable(value)) errors.push(label + ' — Remplacez la saisie par des informations compréhensibles sur votre activité.');
}
const code = String(j.notebook || '').trim().toLowerCase();
if (!/^[a-f0-9]{32}$/.test(code)) errors.push('Copiez les 32 caractères du code de votre carnet.');
else input.notebookId = require('crypto').createHash('sha256').update(code).digest('hex');
if (!input.tone) errors.push('Sélectionnez un ton dans la liste.');
if (input.frequency==='Twice per week' && !settings.hours.includes(j.hour)) errors.push('Choisissez une heure de veille.');
if ([j.website,...splitLinks(j.social)].filter(Boolean).some(x=>!normalizeLink(x))) errors.push('Vérifiez vos liens publics ou retirez les adresses incorrectes.');
if ([...new Set([j.website,...splitLinks(j.social)].map(normalizeLink).filter(Boolean))].length>4) errors.push('Gardez au maximum quatre liens au total.');
if (!/[\p{L}\p{N}]/u.test(input.startup)) errors.push('Renseignez le nom de votre entreprise.');
if (!input.language || (input.language === 'Other' && !input.customLanguage)) errors.push('Choisissez une langue de rédaction ou saisissez-la dans « Autre langue ».');
if (!input.frequency) errors.push('Choisissez une fréquence de veille.');
if (input.frequency === 'Twice per week' && (input.days.length !== 2 || input.days[0] === input.days[1])) errors.push('Choisissez deux jours de veille différents.');
return {json:{valid:!errors.length,errors,input}};

function readHistory(rows,key) {
  if (!/^book-[a-f0-9]{64}$/.test(key)) return [];
  return rows.filter(r=>r.profile_key===key && r.status==='Editorial approved').map(r=>{
    const entry=JSON.parse(r.shortlist_json);
    return {...entry,title:/^(objet|subject)$/i.test(entry.title)?entry.angle:entry.title,at:r.submitted_at,run:r.run_id};
  }).sort((a,b)=>Date.parse(b.at)-Date.parse(a.at));
}
