function readHistory(rows,key) {
  if (!/^book-[a-f0-9]{64}$/.test(key)) return [];
  return rows.filter(r=>r.profile_key===key && r.status==='Editorial approved').map(r=>{
    const entry=JSON.parse(r.shortlist_json);
    return {...entry,title:/^(objet|subject)$/i.test(entry.title)?entry.angle:entry.title,at:r.submitted_at,run:r.run_id};
  }).sort((a,b)=>Date.parse(b.at)-Date.parse(a.at));
}
function clean(value) {
  return String(value||'').normalize('NFKD').replace(/\p{M}/gu,'').toLowerCase().replace(/[^\p{L}\p{N}]+/gu,' ').trim();
}
function tokens(value) {
  const stop=new Set('avec pour dans sont votre notre cette vous plus nous leur mais sans chez les des une aux par sur the and for that with from this how your about'.split(' '));
  return [...new Set(clean(value).split(' ').filter(w=>w && !stop.has(w)))].sort();
}
function alike(a,b) {
  const A=new Set(a), B=new Set(b);
  const n=[...A].filter(x=>B.has(x)).length;
  return n>=3 && n/(A.size+B.size-n)>=0.67;
}
function sameAngle(a,b) {
  return !!clean(a) && (clean(a)===clean(b) || alike(tokens(a),tokens(b)));
}
const j=$('M3. Préparer la remise').first().json;
const history=readHistory($input.all().map(x=>x.json),j.ctx.profile.profile_key);
const digest=require('crypto').createHash('sha256').update(clean(j.approval.finalText)).digest('hex');
const entry={title:((j.draft.format==='Newsletter' ? j.approval.finalText.split(/\r?\n/).map(s=>s.trim()).find(s=>s && !/^(objet|subject)\s*:?$/i.test(s)) : j.draft.title) || j.selection.angle.hook).slice(0,220),angle:j.selection.angle.hook.slice(0,320),format:j.draft.format,digest,words:tokens(j.approval.finalText).slice(0,1500)};
const key='approved-'+j.ctx.run_id;
const match=history.find(h=>h.run!==key && (h.digest===digest || alike(h.words||[],entry.words) || sameAngle(h.angle,entry.angle)));
const blocked=match?[(match.digest===digest?'Vous avez déjà validé ce texte':'Ce contenu est très proche d’un contenu déjà validé')+' le '+new Date(match.at).toLocaleDateString('fr-FR',{timeZone:'Europe/Paris'})+' (« '+match.title+' »). Pour votre prochaine demande, développez une idée différente.']:[];
return [{json:{...j,entry,recordKey:key,approval:{...j.approval,blocked,ok:!blocked.length}}}];

